79	EXTERN int omp_get_device_from_uid(const char *DeviceUid) {
80	  TIMESCOPE();
81	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
82	
83	  if (!DeviceUid) {
84	    ODBG(ODT_Interface) << "Call to " << __func__
85	                        << " returning omp_invalid_device";
86	    return omp_invalid_device;
87	  }
88	  if (is_initial_device_uid(DeviceUid)) {
89	    ODBG(ODT_Interface) << "Call to " << __func__
90	                        << " returning initial device number "
91	                        << omp_get_initial_device();
92	    return omp_get_initial_device();
93	  }
94	
95	  int DeviceNum = omp_invalid_device;
96	
97	  auto ExclusiveDevicesAccessor = PM->getExclusiveDevicesAccessor();
98	  for (const DeviceTy &Device : PM->devices(ExclusiveDevicesAccessor)) {
99	    const char *Uid = Device.RTL->getDevice(Device.RTLDeviceID).getDeviceUid();
100	    if (Uid && strcmp(DeviceUid, Uid) == 0) {
101	      DeviceNum = Device.DeviceID;
102	      break;
103	    }
104	  }
105	
106	  ODBG(ODT_Interface) << "Call to " << __func__ << " returning " << DeviceNum;
107	  return DeviceNum;
108	}
