110	EXTERN const char *omp_get_uid_from_device(int DeviceNum) {
111	  TIMESCOPE();
112	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
113	
114	  if (DeviceNum == omp_invalid_device) {
115	    ODBG(ODT_Interface) << "Call to " << __func__ << " returning nullptr";
116	    return nullptr;
117	  }
118	  if (isInitialDevice(DeviceNum)) {
119	    ODBG(ODT_Interface) << "Call to " << __func__
120	                        << " returning initial device UID";
121	    return GenericPluginTy::getHostDeviceUid();
122	  }
123	
124	  auto DeviceOrErr = PM->getDevice(DeviceNum);
125	  if (!DeviceOrErr)
126	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
127	
128	  const char *Uid =
129	      DeviceOrErr->RTL->getDevice(DeviceOrErr->RTLDeviceID).getDeviceUid();
130	  ODBG(ODT_Interface) << "Call to " << __func__ << " returning " << Uid;
131	  return Uid;
132	}
