222	EXTERN int omp_target_is_present(const void *Ptr, int DeviceNum) {
223	  TIMESCOPE();
224	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
225	  ODBG(ODT_Interface) << "Call to " << __func__ << " for device " << DeviceNum
226	                      << " and address " << Ptr;
227	
228	  if (!Ptr) {
229	    ODBG(ODT_Interface) << "Call to " << __func__
230	                        << " with NULL ptr, returning false";
231	    return false;
232	  }
233	
234	  if (isInitialDevice(DeviceNum)) {
235	    ODBG(ODT_Interface) << "Call to " << __func__ << " on host, returning true";
236	    return true;
237	  }
238	
239	  auto DeviceOrErr = PM->getDevice(DeviceNum);
240	  if (!DeviceOrErr)
241	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
242	
243	  // omp_target_is_present tests whether a host pointer refers to storage that
244	  // is mapped to a given device. However, due to the lack of the storage size,
245	  // only check 1 byte. Cannot set size 0 which checks whether the pointer (zero
246	  // length array) is mapped instead of the referred storage.
247	  TargetPointerResultTy TPR =
248	      DeviceOrErr->getMappingInfo().getTgtPtrBegin(const_cast<void *>(Ptr), 1,
249	                                                   /*UpdateRefCount=*/false,
250	                                                   /*UseHoldRefCount=*/false);
251	  int Rc = TPR.isPresent();
252	  ODBG(ODT_Interface) << "Call to " << __func__ << " returns " << Rc;
253	  return Rc;
254	}
