256	/// Check whether a pointer is accessible from a device.
257	/// Returns true when accessibility is guaranteed otherwise returns false.
258	EXTERN int omp_target_is_accessible(const void *Ptr, size_t Size,
259	                                    int DeviceNum) {
260	  TIMESCOPE();
261	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
262	  ODBG(ODT_Interface) << "Call to " << __func__ << " for device " << DeviceNum
263	                      << ", address " << Ptr << ", size " << Size;
264	
265	  if (!Ptr) {
266	    ODBG(ODT_Interface) << "Call to " << __func__
267	                        << " with NULL ptr returning false";
268	    return false;
269	  }
270	
271	  if (isInitialDevice(DeviceNum)) {
272	    ODBG(ODT_Interface) << "Call to " << __func__ << " on host, returning true";
273	    return true;
274	  }
275	
276	  // The device number must refer to a valid device
277	  auto DeviceOrErr = PM->getDevice(DeviceNum);
278	  if (!DeviceOrErr)
279	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
280	
281	  return DeviceOrErr->isAccessiblePtr(Ptr, Size);
282	}
