284	EXTERN int omp_target_memcpy(void *Dst, const void *Src, size_t Length,
285	                             size_t DstOffset, size_t SrcOffset, int DstDevice,
286	                             int SrcDevice) {
287	  TIMESCOPE_WITH_DETAILS("dst_dev=" + std::to_string(DstDevice) +
288	                         ";src_dev=" + std::to_string(SrcDevice) +
289	                         ";size=" + std::to_string(Length));
290	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
291	  ODBG(ODT_Interface) << "Call to " << __func__ << ", dst device " << DstDevice
292	                      << ", src device " << SrcDevice << ", dst addr " << Dst
293	                      << ", src addr " << Src << ", dst offset " << DstOffset
294	                      << ", src offset " << SrcOffset << ", length " << Length;
295	
296	  if (!Dst || !Src || Length <= 0) {
297	    if (Length == 0) {
298	      ODBG(ODT_Interface) << "Call to " << __func__
299	                          << " with zero length, nothing to do";
300	      return OFFLOAD_SUCCESS;
301	    }
302	
303	    REPORT() << "Call to " << __func__ << " with invalid arguments";
304	    return OFFLOAD_FAIL;
305	  }
306	
307	  int Rc = OFFLOAD_SUCCESS;
308	  void *SrcAddr = (char *)const_cast<void *>(Src) + SrcOffset;
309	  void *DstAddr = (char *)Dst + DstOffset;
310	
311	  if (isInitialDevice(SrcDevice) && isInitialDevice(DstDevice)) {
312	    ODBG(ODT_Interface) << "copy from host to host";
313	    const void *P = memcpy(DstAddr, SrcAddr, Length);
314	    if (P == NULL)
315	      Rc = OFFLOAD_FAIL;
316	  } else if (isInitialDevice(SrcDevice)) {
317	    ODBG(ODT_Interface) << "copy from host to device";
318	    auto DstDeviceOrErr = PM->getDevice(DstDevice);
319	    if (!DstDeviceOrErr)
320	      FATAL_MESSAGE(DstDevice, "%s",
321	                    toString(DstDeviceOrErr.takeError()).c_str());
322	    AsyncInfoTy AsyncInfo(*DstDeviceOrErr);
323	    Rc = DstDeviceOrErr->submitData(DstAddr, SrcAddr, Length, AsyncInfo);
324	  } else if (isInitialDevice(DstDevice)) {
325	    ODBG(ODT_Interface) << "copy from device to host";
326	    auto SrcDeviceOrErr = PM->getDevice(SrcDevice);
327	    if (!SrcDeviceOrErr)
328	      FATAL_MESSAGE(SrcDevice, "%s",
329	                    toString(SrcDeviceOrErr.takeError()).c_str());
330	    AsyncInfoTy AsyncInfo(*SrcDeviceOrErr);
331	    Rc = SrcDeviceOrErr->retrieveData(DstAddr, SrcAddr, Length, AsyncInfo);
332	  } else {
333	    ODBG(ODT_Interface) << "copy from device to device";
334	    auto SrcDeviceOrErr = PM->getDevice(SrcDevice);
335	    if (!SrcDeviceOrErr)
336	      FATAL_MESSAGE(SrcDevice, "%s",
337	                    toString(SrcDeviceOrErr.takeError()).c_str());
338	    AsyncInfoTy AsyncInfo(*SrcDeviceOrErr);
339	    auto DstDeviceOrErr = PM->getDevice(DstDevice);
340	    if (!DstDeviceOrErr)
341	      FATAL_MESSAGE(DstDevice, "%s",
342	                    toString(DstDeviceOrErr.takeError()).c_str());
343	    // First try to use D2D memcpy which is more efficient. If fails, fall back
344	    // to inefficient way.
345	    if (SrcDeviceOrErr->isDataExchangable(*DstDeviceOrErr)) {
346	      AsyncInfoTy AsyncInfo(*SrcDeviceOrErr);
347	      Rc = SrcDeviceOrErr->dataExchange(SrcAddr, *DstDeviceOrErr, DstAddr,
348	                                        Length, AsyncInfo);
349	      if (Rc == OFFLOAD_SUCCESS)
350	        return OFFLOAD_SUCCESS;
351	    }
352	
353	    void *Buffer = malloc(Length);
354	    {
355	      AsyncInfoTy AsyncInfo(*SrcDeviceOrErr);
356	      Rc = SrcDeviceOrErr->retrieveData(Buffer, SrcAddr, Length, AsyncInfo);
357	    }
358	    if (Rc == OFFLOAD_SUCCESS) {
359	      AsyncInfoTy AsyncInfo(*DstDeviceOrErr);
360	      Rc = DstDeviceOrErr->submitData(DstAddr, Buffer, Length, AsyncInfo);
361	    }
362	    free(Buffer);
363	  }
364	
365	  ODBG(ODT_Interface) << __func__ << " returns " << Rc;
366	  return Rc;
367	}
