369	// The helper function that calls omp_target_memcpy or omp_target_memcpy_rect
370	static int libomp_target_memcpy_async_task(int32_t Gtid, kmp_task_t *Task) {
371	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
372	  if (Task == nullptr)
373	    return OFFLOAD_FAIL;
374	
375	  TargetMemcpyArgsTy *Args = (TargetMemcpyArgsTy *)Task->shareds;
376	
377	  if (Args == nullptr)
378	    return OFFLOAD_FAIL;
379	
380	  // Call blocked version
381	  int Rc = OFFLOAD_SUCCESS;
382	  if (Args->IsRectMemcpy) {
383	    Rc = omp_target_memcpy_rect(
384	        Args->Dst, Args->Src, Args->ElementSize, Args->NumDims, Args->Volume,
385	        Args->DstOffsets, Args->SrcOffsets, Args->DstDimensions,
386	        Args->SrcDimensions, Args->DstDevice, Args->SrcDevice);
387	
388	    ODBG(ODT_Interface) << " omp_target_memcpy_rect returns " << Rc;
389	  } else {
390	    Rc = omp_target_memcpy(Args->Dst, Args->Src, Args->Length, Args->DstOffset,
391	                           Args->SrcOffset, Args->DstDevice, Args->SrcDevice);
392	
393	    ODBG(ODT_Interface) << " omp_target_memcpy returns " << Rc;
394	  }
395	
396	  // Release the arguments object
397	  delete Args;
398	
399	  return Rc;
400	}
