402	static int libomp_target_memset_async_task(int32_t Gtid, kmp_task_t *Task) {
403	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
404	  if (!Task)
405	    return OFFLOAD_FAIL;
406	
407	  auto *Args = reinterpret_cast<TargetMemsetArgsTy *>(Task->shareds);
408	  if (!Args)
409	    return OFFLOAD_FAIL;
410	
411	  // call omp_target_memset()
412	  omp_target_memset(Args->Ptr, Args->C, Args->N, Args->DeviceNum);
413	
414	  delete Args;
415	
416	  return OFFLOAD_SUCCESS;
417	}
