419	static inline void
420	convertDepObjVector(llvm::SmallVector<kmp_depend_info_t> &Vec, int DepObjCount,
421	                    omp_depend_t *DepObjList) {
422	  for (int i = 0; i < DepObjCount; ++i) {
423	    omp_depend_t DepObj = DepObjList[i];
424	    Vec.push_back(*((kmp_depend_info_t *)DepObj));
425	  }
426	}
