428	template <class T>
429	static inline int
430	libomp_helper_task_creation(T *Args, int (*Fn)(int32_t, kmp_task_t *),
431	                            int DepObjCount, omp_depend_t *DepObjList) {
432	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
433	  // Create global thread ID
434	  int Gtid = __kmpc_global_thread_num(nullptr);
435	
436	  // Setup the hidden helper flags
437	  int32_t Flags = 0;
438	  kmp_tasking_flags_t *InputFlags = (kmp_tasking_flags_t *)&Flags;
439	  InputFlags->hidden_helper = 1;
440	
441	  // Alloc the helper task
442	  kmp_task_t *Task = __kmpc_omp_target_task_alloc(
443	      nullptr, Gtid, Flags, sizeof(kmp_task_t), 0, Fn, -1);
444	  if (!Task) {
445	    delete Args;
446	    return OFFLOAD_FAIL;
447	  }
448	
449	  // Setup the arguments for the helper task
450	  Task->shareds = Args;
451	
452	  // Convert types of depend objects
453	  llvm::SmallVector<kmp_depend_info_t> DepObjs;
454	  convertDepObjVector(DepObjs, DepObjCount, DepObjList);
455	
456	  // Launch the helper task
457	  int Rc = __kmpc_omp_task_with_deps(nullptr, Gtid, Task, DepObjCount,
458	                                     DepObjs.data(), 0, nullptr);
459	
460	  return Rc;
461	}
