463	EXTERN void *omp_target_memset(void *Ptr, int ByteVal, size_t NumBytes,
464	                               int DeviceNum) {
465	  TIMESCOPE();
466	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
467	  ODBG(ODT_Interface) << "Call to " << __func__ << ", device " << DeviceNum
468	                      << ", device pointer " << Ptr << ", size " << NumBytes;
469	
470	  // Behave as a no-op if N==0 or if Ptr is nullptr (as a useful implementation
471	  // of unspecified behavior, see OpenMP spec).
472	  if (!Ptr || NumBytes == 0) {
473	    return Ptr;
474	  }
475	
476	  if (isInitialDevice(DeviceNum)) {
477	    ODBG(ODT_Interface) << "filling memory on host via memset";
478	    memset(Ptr, ByteVal, NumBytes); // ignore return value, memset() cannot fail
479	  } else {
480	    OMPT_IF_BUILT(InterfaceRAII TargetMemsetRAII(
481	        RegionInterface.getCallbacks<ompt_target_data_memset>(), DeviceNum,
482	        nullptr, const_cast<void *>(Ptr), NumBytes,
483	        __builtin_return_address(0)));
484	
485	    auto DeviceOrErr = PM->getDevice(DeviceNum);
486	    if (!DeviceOrErr)
487	      FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
488	    AsyncInfoTy AsyncInfo(*DeviceOrErr);
489	    if (auto Error = DeviceOrErr->RTL->getDevice(DeviceOrErr->RTLDeviceID)
490	                         .dataFill(Ptr, &ByteVal, 1, NumBytes, AsyncInfo)) {
491	      ODBG(ODT_Interface)
492	          << __func__ << " failed to fill memory due to error with dataFill";
493	      // If the dataFill failed, let's just not do anything.
494	      // omp_target_memset does not have any good way to fail.
495	      // Depending on the RTL implementation, the application will
496	      // abort anyway.
497	    }
498	  }
499	
500	  ODBG(ODT_Interface) << __func__ << " returns " << Ptr;
501	  return Ptr;
502	}
