504	EXTERN void *omp_target_memset_async(void *Ptr, int ByteVal, size_t NumBytes,
505	                                     int DeviceNum, int DepObjCount,
506	                                     omp_depend_t *DepObjList) {
507	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
508	  ODBG(ODT_Interface) << "Call to " << __func__ << ", device " << DeviceNum
509	                      << ", device pointer " << Ptr << ", size " << NumBytes;
510	
511	  // Behave as a no-op if N==0 or if Ptr is nullptr (as a useful implementation
512	  // of unspecified behavior, see OpenMP spec).
513	  if (!Ptr || NumBytes == 0)
514	    return Ptr;
515	
516	  // Create the task object to deal with the async invocation
517	  auto *Args = new TargetMemsetArgsTy{Ptr, ByteVal, NumBytes, DeviceNum};
518	
519	  // omp_target_memset_async() cannot fail via a return code, so ignore the
520	  // return code of the helper function
521	  (void)libomp_helper_task_creation(Args, &libomp_target_memset_async_task,
522	                                    DepObjCount, DepObjList);
523	
524	  return Ptr;
525	}
