527	EXTERN int omp_target_memcpy_async(void *Dst, const void *Src, size_t Length,
528	                                   size_t DstOffset, size_t SrcOffset,
529	                                   int DstDevice, int SrcDevice,
530	                                   int DepObjCount, omp_depend_t *DepObjList) {
531	  TIMESCOPE_WITH_DETAILS("dst_dev=" + std::to_string(DstDevice) +
532	                         ";src_dev=" + std::to_string(SrcDevice) +
533	                         ";size=" + std::to_string(Length));
534	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
535	  ODBG(ODT_Interface) << "Call to " << __func__ << ", dst device " << DstDevice
536	                      << ", src device " << SrcDevice << ", dst addr " << Dst
537	                      << ", src addr " << Src << ", dst offset " << DstOffset
538	                      << ", src offset " << SrcOffset << ", length " << Length;
539	
540	  // Check the source and dest address
541	  if (Dst == nullptr || Src == nullptr)
542	    return OFFLOAD_FAIL;
543	
544	  // Create task object
545	  TargetMemcpyArgsTy *Args = new TargetMemcpyArgsTy(
546	      Dst, Src, Length, DstOffset, SrcOffset, DstDevice, SrcDevice);
547	
548	  // Create and launch helper task
549	  int Rc = libomp_helper_task_creation(Args, &libomp_target_memcpy_async_task,
550	                                       DepObjCount, DepObjList);
551	
552	  ODBG(ODT_Interface) << __func__ << " returns " << Rc;
553	  return Rc;
554	}
555	
556	EXTERN int
557	omp_target_memcpy_rect(void *Dst, const void *Src, size_t ElementSize,
558	                       int NumDims, const size_t *Volume,
559	                       const size_t *DstOffsets, const size_t *SrcOffsets,
560	                       const size_t *DstDimensions, const size_t *SrcDimensions,
561	                       int DstDevice, int SrcDevice) {
562	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
563	  ODBG(ODT_Interface) << "Call to " << __func__ << ", dst device " << DstDevice
564	                      << ", src device " << SrcDevice << ", dst addr " << Dst
565	                      << ", src addr " << Src << ", dst offsets " << DstOffsets
566	                      << ", src offsets " << SrcOffsets << ", dst dims "
567	                      << DstDimensions << ", src dims " << SrcDimensions
568	                      << ", volume " << Volume << ", element size "
569	                      << ElementSize << ", num_dims " << NumDims;
570	
571	  if (!(Dst || Src)) {
572	    ODBG(ODT_Interface) << "Call to " << __func__
573	                        << " returns max supported dimensions " << INT_MAX;
574	    return INT_MAX;
575	  }
576	
577	  if (!Dst || !Src || ElementSize < 1 || NumDims < 1 || !Volume ||
578	      !DstOffsets || !SrcOffsets || !DstDimensions || !SrcDimensions) {
579	    REPORT() << "Call to " << __func__ << " with invalid arguments";
580	    return OFFLOAD_FAIL;
581	  }
582	
583	  int Rc;
584	  if (NumDims == 1) {
585	    Rc = omp_target_memcpy(Dst, Src, ElementSize * Volume[0],
586	                           ElementSize * DstOffsets[0],
587	                           ElementSize * SrcOffsets[0], DstDevice, SrcDevice);
588	  } else {
589	    size_t DstSliceSize = ElementSize;
590	    size_t SrcSliceSize = ElementSize;
591	    for (int I = 1; I < NumDims; ++I) {
592	      DstSliceSize *= DstDimensions[I];
593	      SrcSliceSize *= SrcDimensions[I];
594	    }
595	
596	    size_t DstOff = DstOffsets[0] * DstSliceSize;
597	    size_t SrcOff = SrcOffsets[0] * SrcSliceSize;
598	    for (size_t I = 0; I < Volume[0]; ++I) {
599	      Rc = omp_target_memcpy_rect(
600	          (char *)Dst + DstOff + DstSliceSize * I,
601	          (char *)const_cast<void *>(Src) + SrcOff + SrcSliceSize * I,
602	          ElementSize, NumDims - 1, Volume + 1, DstOffsets + 1, SrcOffsets + 1,
603	          DstDimensions + 1, SrcDimensions + 1, DstDevice, SrcDevice);
604	
605	      if (Rc) {
606	        ODBG(ODT_Interface)
607	            << "Recursive call to " << __func__ << " returns unsuccessfully";
608	        return Rc;
609	      }
610	    }
611	  }
612	
613	  ODBG(ODT_Interface) << " returns " << Rc;
614	  return Rc;
615	}
616	
617	EXTERN int omp_target_memcpy_rect_async(
618	    void *Dst, const void *Src, size_t ElementSize, int NumDims,
619	    const size_t *Volume, const size_t *DstOffsets, const size_t *SrcOffsets,
620	    const size_t *DstDimensions, const size_t *SrcDimensions, int DstDevice,
621	    int SrcDevice, int DepObjCount, omp_depend_t *DepObjList) {
622	  TIMESCOPE_WITH_DETAILS("dst_dev=" + std::to_string(DstDevice) +
623	                         ";src_dev=" + std::to_string(SrcDevice) +
624	                         ";size=" + std::to_string(ElementSize) +
625	                         ";num_dims=" + std::to_string(NumDims));
626	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
627	  ODBG(ODT_Interface) << "Call to " << __func__ << ", dst device " << DstDevice
628	                      << ", src device " << SrcDevice << ", dst addr " << Dst
629	                      << ", src addr " << Src << ", dst offsets " << DstOffsets
630	                      << ", src offsets " << SrcOffsets << ", dst dims "
631	                      << DstDimensions << ", src dims " << SrcDimensions
632	                      << ", volume " << Volume << ", element size "
633	                      << ElementSize << ", num_dims " << NumDims;
634	
635	  // Need to check this first to not return OFFLOAD_FAIL instead
636	  if (!Dst && !Src) {
637	    ODBG(ODT_Interface) << "Call to " << __func__
638	                        << " returns max supported dimensions " << INT_MAX;
639	    return INT_MAX;
640	  }
641	
642	  // Check the source and dest address
643	  if (Dst == nullptr || Src == nullptr)
644	    return OFFLOAD_FAIL;
645	
646	  // Create task object
647	  TargetMemcpyArgsTy *Args = new TargetMemcpyArgsTy(
648	      Dst, Src, ElementSize, NumDims, Volume, DstOffsets, SrcOffsets,
649	      DstDimensions, SrcDimensions, DstDevice, SrcDevice);
650	
651	  // Create and launch helper task
652	  int Rc = libomp_helper_task_creation(Args, &libomp_target_memcpy_async_task,
653	                                       DepObjCount, DepObjList);
654	
655	  ODBG(ODT_Interface) << __func__ << " returns " << Rc;
656	  return Rc;
657	}
658	
659	EXTERN int omp_target_associate_ptr(const void *HostPtr, const void *DevicePtr,
660	                                    size_t Size, size_t DeviceOffset,
661	                                    int DeviceNum) {
662	  TIMESCOPE();
663	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
664	  ODBG(ODT_Interface) << "Call to " << __func__ << " with host_ptr " << HostPtr
665	                      << ", device_ptr " << DevicePtr << ", size " << Size
666	                      << ", device_offset " << DeviceOffset << ", device_num "
667	                      << DeviceNum;
668	
669	  if (!HostPtr || !DevicePtr || Size <= 0) {
670	    REPORT() << "Call to " << __func__ << " with invalid arguments";
671	    return OFFLOAD_FAIL;
672	  }
673	
674	  if (isInitialDevice(DeviceNum)) {
675	    REPORT() << __func__ << ": no association possible on the host";
676	    return OFFLOAD_FAIL;
677	  }
678	
679	  auto DeviceOrErr = PM->getDevice(DeviceNum);
680	  if (!DeviceOrErr)
681	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
682	
683	  void *DeviceAddr = (void *)((uint64_t)DevicePtr + (uint64_t)DeviceOffset);
684	
685	  OMPT_IF_BUILT(InterfaceRAII(
686	      RegionInterface.getCallbacks<ompt_target_data_associate>(), DeviceNum,
687	      const_cast<void *>(HostPtr), const_cast<void *>(DevicePtr), Size,
688	      __builtin_return_address(0)));
689	
690	  int Rc = DeviceOrErr->getMappingInfo().associatePtr(
691	      const_cast<void *>(HostPtr), const_cast<void *>(DeviceAddr), Size);
692	  ODBG(ODT_Interface) << __func__ << " returns " << Rc;
693	  return Rc;
694	}
695	
696	EXTERN int omp_target_disassociate_ptr(const void *HostPtr, int DeviceNum) {
697	  TIMESCOPE();
698	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
699	  ODBG(ODT_Interface) << "Call to " << __func__ << " with host_ptr " << HostPtr
700	                      << ", device_num " << DeviceNum;
701	
702	  if (!HostPtr) {
703	    REPORT() << "Call to " << __func__ << " with invalid host_ptr";
704	    return OFFLOAD_FAIL;
705	  }
706	
707	  if (isInitialDevice(DeviceNum)) {
708	    REPORT() << __func__ << ": no association possible on the host";
709	    return OFFLOAD_FAIL;
710	  }
711	
712	  auto DeviceOrErr = PM->getDevice(DeviceNum);
713	  if (!DeviceOrErr)
714	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
715	
716	  OMPT_IF_BUILT(InterfaceRAII(
717	      RegionInterface.getCallbacks<ompt_target_data_disassociate>(), DeviceNum,
718	      const_cast<void *>(HostPtr),
719	      /*DevicePtr=*/nullptr, /*Size=*/0, __builtin_return_address(0)));
720	
721	  int Rc = DeviceOrErr->getMappingInfo().disassociatePtr(
722	      const_cast<void *>(HostPtr));
723	  ODBG(ODT_Interface) << __func__ << " returns " << Rc;
724	  return Rc;
725	}
726	
727	EXTERN void *omp_get_mapped_ptr(const void *Ptr, int DeviceNum) {
728	  TIMESCOPE();
729	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
730	  ODBG(ODT_Interface) << "Call to " << __func__ << " with ptr " << Ptr
731	                      << ", device_num " << DeviceNum;
732	
733	  if (!Ptr) {
734	    REPORT() << "Call to " << __func__ << " with nullptr.";
735	    return nullptr;
736	  }
737	
738	  int NumDevices = omp_get_initial_device();
739	  if (isInitialDevice(DeviceNum)) {
740	    ODBG(ODT_Interface) << "Device " << DeviceNum
741	                        << " is initial device, returning Ptr " << Ptr;
742	    return const_cast<void *>(Ptr);
743	  }
744	
745	  if (NumDevices <= DeviceNum) {
746	    ODBG(ODT_Interface) << "DeviceNum " << DeviceNum
747	                        << " is invalid, returning nullptr.";
748	    return nullptr;
749	  }
750	
751	  auto DeviceOrErr = PM->getDevice(DeviceNum);
752	  if (!DeviceOrErr)
753	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
754	
755	  TargetPointerResultTy TPR =
756	      DeviceOrErr->getMappingInfo().getTgtPtrBegin(const_cast<void *>(Ptr), 1,
757	                                                   /*UpdateRefCount=*/false,
758	                                                   /*UseHoldRefCount=*/false);
759	  if (!TPR.isPresent()) {
760	    ODBG(ODT_Interface) << "Ptr " << Ptr
761	                        << "is not present on device %d, returning nullptr.";
762	    return nullptr;
763	  }
764	
765	  ODBG(ODT_Interface) << __func__ << " returns " << TPR.TargetPointer << ".";
766	
767	  return TPR.TargetPointer;
768	}
769	
770	// This routine gets called from the Host RTL at sync points (taskwait, barrier,
771	// ...) so we can synchronize the necessary objects from the offload side.
772	EXTERN void __tgt_target_sync(ident_t *loc_ref, int gtid, void *current_task,
773	                              void *event) {
774	  if (!RTLAlive)
775	    return;
776	
777	  RTLOngoingSyncs++;
778	  if (!RTLAlive) {
779	    RTLOngoingSyncs--;
780	    return;
781	  }
782	
783	  syncImplicitInterops(gtid, event);
784	
785	  RTLOngoingSyncs--;
786	}
